public static String naMale(String text) {
    char tab[] = text.toCharArray();
    for (int i = 0; i < tab.length; i++) {
        if (tab[i] >= 'A' && tab[i] <= 'Z') {
            tab[i] = tab[i] + 32;
        }
    }
    return new String(tab);
}

public static void main(String[] args) {
    System.out.println(naMale("KOT Ma 3 LAPY"));
}

public static String zmienPierwsza(String text, char c) {
    char tab[] = text.toCharArray();
    tab[0] = c;
    return "" + tab;
}

public static void main(String[] args) {
    System.out.println(zmienPierwsza("Ala", 'X'));
}

public static int ileSpacji(String text) {
    int licz = 0;
    for (int i = 0; i < text.length; i++) {
        if (text.charAt(i) == ' ') {
            licz++;
        }
    }
    return licz;
}

public static int ileKropek(char tab[]) {
    int licz = 0;
    for (int i = 0; i < tab.length(); i++) {
        if (tab[i] == '.') {
            licz++;
        }
    }
    return licz;
}

public static void main(String[] args) {
    System.out.println(ileSpacji("ala ma kota"));
    char k[] = "a.b.c".toCharArray();
    System.out.println(ileKropek(k));
}

public static String wielkaPierwsza(String text) {
    text.charAt(0) = (char) (text.charAt(0) - 32);
    return text;
}

public static void main(String[] args) {
    System.out.println(wielkaPierwsza("ola"));
}
